args.sparql:
SELECT ?senator ?county ?countyLabel WHERE {
  ?senator wdt:P1303 wd:Q2757502 ;
           wdt:P102 wd:Q6594893 ;
           wdt:P17 wd:Q230 ;
           wdt:P131 ?county .
  ?county rdfs:label ?countyLabel .
  FILTER (LANG(?countyLabel) = "en")
}

